private int minPath(List<List<Integer>> triangle, int i, int j) {
    if (i == triangle.size() - 1) {
        return triangle.get(i).get(j);
    }
    int left = minPath(triangle, i + 1, j);
    int right = minPath(triangle, i + 1, j + 1);
    return triangle.get(i).get(j) + Math.min(left, right);
}

