def minimumTotal(self, triangle: list[list[int]]) -> int:
    from functools import lru_cache
    n = len(triangle)

    @lru_cache(maxsize=None)
    def solve(i: int, j: int) -> int:
        if i == n - 1:
            return triangle[i][j]
        left = solve(i + 1, j)
        right = solve(i + 1, j + 1)
        return triangle[i][j] + min(left, right)

    return solve(0, 0)

